import sys
import ast
import pathlib

# ---- Configuration ----
SOURCE_FILE = "/src/dsvw.py"
# Common names that may hold untrusted input
UNTRUSTED_VARS = {
    "params", "request", "query", "data", "payload", "user_input",
    "form", "body", "json", "post", "get", "input", "value"
}
# ---- Helper functions ----
def is_untrusted_name(node):
    """Return True if the AST node is a Name that matches a known untrusted variable."""
    return isinstance(node, ast.Name) and node.id in UNTRUSTED_VARS

def contains_untrusted(node):
    """Recursively check if an expression tree contains an untrusted variable."""
    if is_untrusted_name(node):
        return True
    for child in ast.iter_child_nodes(node):
        if contains_untrusted(child):
            return True
    return False

def check_sql_injection(tree):
    """
    Detect calls to .execute (SQLAlchemy) where the SQL argument is constructed
    from untrusted input via string concatenation, f‑strings, or format().
    """
    for node in ast.walk(tree):
        # Look for Call nodes where the callee is an attribute named "execute"
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
            if node.func.attr != "execute":
                continue

            # Ensure there is at least one positional argument (the SQL statement)
            if not node.args:
                continue

            sql_arg = node.args[0]

            # 1. Binary string concatenation (e.g., "SELECT ... " + user_input)
            if isinstance(sql_arg, ast.BinOp) and isinstance(sql_arg.op, ast.Add):
                if contains_untrusted(sql_arg):
                    return True

            # 2. f‑string / JoinedStr containing untrusted Name nodes
            if isinstance(sql_arg, ast.JoinedStr):
                for value in sql_arg.values:
                    if isinstance(value, ast.FormattedValue) and contains_untrusted(value.value):
                        return True

            # 3. .format(...) on a string where arguments include untrusted vars
            if isinstance(sql_arg, ast.Call) and isinstance(sql_arg.func, ast.Attribute):
                if sql_arg.func.attr == "format":
                    for arg in sql_arg.args:
                        if contains_untrusted(arg):
                            return True
                    for kw in sql_arg.keywords:
                        if contains_untrusted(kw.value):
                            return True

            # 4. Direct usage of an untrusted variable as the SQL argument
            if contains_untrusted(sql_arg):
                return True

    return False

# ---- Main execution ----
def main():
    src_path = pathlib.Path(SOURCE_FILE)
    if not src_path.is_file():
        print(f"VALIDATION_ERROR: Source file not found at {SOURCE_FILE}")
        sys.exit(1)

    try:
        with src_path.open("r", encoding="utf-8") as f:
            source = f.read()
        tree = ast.parse(source, filename=SOURCE_FILE)
    except Exception as e:
        print(f"VALIDATION_ERROR: Failed to parse source – {e}")
        sys.exit(1)

    if check_sql_injection(tree):
        print("VALIDATION_SUCCESS: Detected raw SQL execution built from untrusted input.")
        sys.exit(0)

    # No vulnerable pattern found
    sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import ast

# Validation for dynamic-urllib-use-detected:
# Detect urllib.request.urlopen called with a value taken directly from user-controlled dict (e.g., params['...']).

SOURCE_FILE = "/src/dsvw.py"

def is_urllib_urlopen(node):
    """Return True if the Call node is urllib.request.urlopen."""
    # Must be a Call where func is an Attribute chain: urllib.request.urlopen
    if not isinstance(node, ast.Call):
        return False
    func = node.func
    if not isinstance(func, ast.Attribute) or func.attr != "urlopen":
        return False
    # func.value should be an Attribute named 'request'
    request_attr = func.value
    if not isinstance(request_attr, ast.Attribute) or request_attr.attr != "request":
        return False
    # request_attr.value should be Name 'urllib'
    if not isinstance(request_attr.value, ast.Name) or request_attr.value.id != "urllib":
        return False
    return True

def arg_is_user_input(arg):
    """Return True if the argument originates from the 'params' dict (subscript or .get)."""
    # params['key']
    if isinstance(arg, ast.Subscript):
        if isinstance(arg.value, ast.Name) and arg.value.id == "params":
            return True
    # params.get('key')
    if isinstance(arg, ast.Call):
        if isinstance(arg.func, ast.Attribute):
            if arg.func.attr == "get" and isinstance(arg.func.value, ast.Name) and arg.func.value.id == "params":
                return True
    return False

def check_vuln(tree):
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and is_urllib_urlopen(node):
            if node.args:
                if arg_is_user_input(node.args[0]):
                    return True
    return False

def main():
    try:
        with open(SOURCE_FILE, "r", encoding="utf-8") as f:
            source = f.read()
        tree = ast.parse(source, filename=SOURCE_FILE)
        if check_vuln(tree):
            print("VALIDATION_SUCCESS: urllib.request.urlopen receives unsanitized user input.")
            sys.exit(0)
    except Exception as e:
        print(f"VALIDATION_ERROR: {e}", file=sys.stderr)

    sys.exit(1)

if __name__ == "__main__":
    main()
